// v16.xx, HIS REPORT (2026-10-03): A SETTINGS CHANGE THREW HIM BACK TO THE TOP. Every row click rebuilds the list, and the rebuild
// lost the scroll and the focused control, so a controller walking down the page went back to the first row after each change.
// The scroll of the list and of anything above it, the focused button and the pad highlight are kept across the rebuild, by id.
function setKeep(host){
  var sc=[], e=host, a=document.activeElement, pf=(typeof PAD==='object'&&PAD&&PAD.focus)?PAD.focus:null;
  while(e&&e!==document.body){ if(e.scrollTop>0) sc.push([e,e.scrollTop]); e=e.parentNode; }
  return {sc:sc,id:(a&&a.id)||'',pf:(pf&&pf.id)||''};
}
function setRestore(k){
  var i, f;
  if(!k) return;
  for(i=0;i<k.sc.length;i++){ try{ k.sc[i][0].scrollTop=k.sc[i][1]; }catch(_s){} }
  if(k.id){ f=document.getElementById(k.id); if(f&&f.focus){ try{ f.focus({preventScroll:true}); }catch(_f){ try{ f.focus(); }catch(_f2){} } } }
  if(k.pf){ f=document.getElementById(k.pf); if(f&&typeof padSetFocus==='function'&&(!PAD.focus||!PAD.focus.isConnected)){ try{ padSetFocus(f); }catch(_p){} } }
  for(i=0;i<k.sc.length;i++){ try{ k.sc[i][0].scrollTop=k.sc[i][1]; }catch(_s2){} }
}
function renderSettings(){
  var host=document.getElementById('setlist'), _keep=setKeep(host);
  try{ renderSettingsInner(host); }finally{ setRestore(_keep); }
}
function renderSettingsInner(host){

check:
{v:'VER',what:'a Settings change keeps its place: with the list scrolled and a button focused, a rebuild leaves the scroll where it was, the same button focused and the pad highlight on it',
 run:function(){
   if(typeof renderSettings!=='function'||typeof setKeep!=='function') return 'a Settings change still rebuilds the list from the top';
   var md=document.getElementById('settingsmodal'), host=document.getElementById('setlist'), bad=[], got, b, was=md&&md.classList.contains('on'), mh, ov;
   if(!md||!host) return 'SKIP: no Settings list in this fixture';
   mh=host.style.maxHeight; ov=host.style.overflowY;
   try{
     md.classList.add('on'); renderSettings();
     host.style.maxHeight='220px'; host.style.overflowY='auto';
     host.scrollTop=150; got=host.scrollTop;
     if(got<100) return 'SKIP: the list would not scroll in this pane ('+got+')';
     b=document.getElementById('set_kb'); if(!b) return 'SKIP: no kid row to focus';
     try{ b.focus({preventScroll:true}); }catch(_f){ b.focus(); }
     if(typeof padSetFocus==='function') padSetFocus(b);
     host.scrollTop=got;
     renderSettings();
     if(Math.abs(host.scrollTop-got)>2) bad.push('a rebuild moved the list from '+got+' to '+host.scrollTop);
     if(!document.activeElement||document.activeElement.id!=='set_kb') bad.push('the focused button was lost (now '+((document.activeElement&&document.activeElement.id)||'nothing')+')');
     if(typeof PAD==='object'&&PAD&&(!PAD.focus||PAD.focus.id!=='set_kb'||!PAD.focus.isConnected)) bad.push('the pad highlight was lost');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ host.style.maxHeight=mh; host.style.overflowY=ov; try{ if(typeof padSetFocus==='function') padSetFocus(null); }catch(_p){} try{ if(document.activeElement&&document.activeElement.blur) document.activeElement.blur(); }catch(_b){} if(!was) md.classList.remove('on'); }
   return bad.length?bad.join('; '):null; }},
